import{_ as e,o,c as a,a2 as n}from"./chunks/framework.DQhM5RF8.js";const u=JSON.parse('{"title":"Enchantment Rules, Conflicts & Drawbacks","description":"","frontmatter":{},"headers":[],"relativePath":"enchants/conflicts.md","filePath":"enchants/conflicts.md"}'),r={name:"enchants/conflicts.md"};function s(l,t,i,h,c,d){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="enchantment-rules-conflicts-drawbacks" tabindex="-1">Enchantment Rules, Conflicts &amp; Drawbacks <a class="header-anchor" href="#enchantment-rules-conflicts-drawbacks" aria-label="Permalink to &quot;Enchantment Rules, Conflicts &amp; Drawbacks&quot;">​</a></h1><p>Just like in regular Minecraft where you cannot put <strong>Fortune</strong> and <strong>Silk Touch</strong> on the same pickaxe, LlamaCraft has rules for what enchants can go together, what enchants conflict, and which ones have special drawbacks.</p><hr><h2 id="how-to-put-custom-enchants-on-your-gear" tabindex="-1">How to Put Custom Enchants on Your Gear <a class="header-anchor" href="#how-to-put-custom-enchants-on-your-gear" aria-label="Permalink to &quot;How to Put Custom Enchants on Your Gear&quot;">​</a></h2><ol><li><strong>Get an Enchanted Book</strong>: Catch a <strong>Sealed Tome</strong> by fishing (or buy one from another player in <code>/ah</code>).</li><li><strong>Right-Click to Open</strong>: Right-click the sealed tome in your hand to reveal the custom enchantment.</li><li><strong>Use an Anvil</strong>: Place your gear on the left side of an anvil and the custom book on the right side.</li><li><strong>Spend XP Levels</strong>: Pay the XP cost to combine the magic into your gear!</li></ol><hr><h2 id="enchants-with-drawbacks-trade-offs" tabindex="-1">Enchants with Drawbacks (Trade-Offs) <a class="header-anchor" href="#enchants-with-drawbacks-trade-offs" aria-label="Permalink to &quot;Enchants with Drawbacks (Trade-Offs)&quot;">​</a></h2><p>Most enchants give you pure bonuses, but a few powerful enchants have a trade-off you should know about before using them:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Enchant</th><th style="text-align:left;">Where It Goes</th><th style="text-align:left;">The Big Bonus</th><th style="text-align:left;">The Drawback (The Catch)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Glass Cannon</strong></td><td style="text-align:left;">Sword</td><td style="text-align:left;">You deal <strong>+25% more damage</strong> on every hit!</td><td style="text-align:left;">You also <strong>take +25% more damage</strong> from all incoming hits. High risk, high reward.</td></tr><tr><td style="text-align:left;"><strong>Berserker</strong></td><td style="text-align:left;">Sword &amp; Axe</td><td style="text-align:left;">When your health drops dangerously low, you get a huge burst of Strength and Speed for 30 seconds.</td><td style="text-align:left;">Once the 30 seconds finish, your character suffers from exhaustion and weakness for a short time.</td></tr><tr><td style="text-align:left;"><strong>Exploding Arrows</strong></td><td style="text-align:left;">Bow &amp; Crossbow</td><td style="text-align:left;">Arrows explode like TNT when they hit an enemy.</td><td style="text-align:left;">If you are fighting out in the wild (outside protected claims), the blast can blow up nearby blocks and hurt teammates standing too close.</td></tr></tbody></table><hr><h2 id="custom-enchant-conflicts-you-can-only-pick-one" tabindex="-1">Custom Enchant Conflicts (You Can Only Pick One) <a class="header-anchor" href="#custom-enchant-conflicts-you-can-only-pick-one" aria-label="Permalink to &quot;Custom Enchant Conflicts (You Can Only Pick One)&quot;">​</a></h2><p>To keep PvP fair and balanced, certain enchants belong to a <strong>conflict group</strong>. If your sword or bow already has one enchant from the group, you cannot add another one from the same group:</p><h3 id="_1-sword-damage-boosters-pick-only-1" tabindex="-1">1. Sword Damage Boosters (Pick Only 1) <a class="header-anchor" href="#_1-sword-damage-boosters-pick-only-1" aria-label="Permalink to &quot;1. Sword Damage Boosters (Pick Only 1)&quot;">​</a></h3><p>You cannot stack multiple bonus damage styles on the same sword. Choose one:</p><ul><li><strong>Executioner</strong>: Deals extra damage to enemies that are already low on health.</li><li><strong>Backstab</strong>: Deals extra damage when hitting someone from behind.</li><li><strong>Bloodlust</strong>: Deals extra damage each time you land consecutive hits.</li><li><strong>Glass Cannon</strong>: Flat +25% bonus damage, but you take +25% more damage.</li></ul><h3 id="_2-sword-healing-powers-pick-only-1" tabindex="-1">2. Sword Healing Powers (Pick Only 1) <a class="header-anchor" href="#_2-sword-healing-powers-pick-only-1" aria-label="Permalink to &quot;2. Sword Healing Powers (Pick Only 1)&quot;">​</a></h3><p>Choose how your sword heals you:</p><ul><li><strong>Life Steal</strong>: Steals health from every hit to give you golden absorption hearts.</li><li><strong>Triumph</strong>: Gives you a big burst of healed hearts whenever you defeat an enemy.</li></ul><h3 id="_3-sword-effects-pick-only-1" tabindex="-1">3. Sword Effects (Pick Only 1) <a class="header-anchor" href="#_3-sword-effects-pick-only-1" aria-label="Permalink to &quot;3. Sword Effects (Pick Only 1)&quot;">​</a></h3><p>Choose which status effect your sword gives opponents:</p><ul><li><strong>Venom</strong>: Poisons the target.</li><li><strong>Wither Blade</strong>: Withers the target with black hearts.</li><li><strong>Bleed</strong>: Deals true bleeding damage that ignores armor.</li></ul><h3 id="_4-bow-precision-pick-only-1" tabindex="-1">4. Bow Precision (Pick Only 1) <a class="header-anchor" href="#_4-bow-precision-pick-only-1" aria-label="Permalink to &quot;4. Bow Precision (Pick Only 1)&quot;">​</a></h3><p>Choose your shooting style:</p><ul><li><strong>Marksman</strong>: Deals more damage the farther away your target is (great for snipers).</li><li><strong>Headshot</strong>: Deals massive bonus damage when hitting enemies directly in the head.</li></ul><h3 id="_5-mace-smash-powers-pick-only-1" tabindex="-1">5. Mace Smash Powers (Pick Only 1) <a class="header-anchor" href="#_5-mace-smash-powers-pick-only-1" aria-label="Permalink to &quot;5. Mace Smash Powers (Pick Only 1)&quot;">​</a></h3><p>Choose your heavy mace impact effect:</p><ul><li><strong>Gravity Well</strong>: Pulls all nearby players toward your slam.</li><li><strong>Aftershock</strong>: Creates a slow-motion shockwave on the ground.</li></ul><hr><h2 id="vanilla-minecraft-conflicts-reminder" tabindex="-1">Vanilla Minecraft Conflicts Reminder <a class="header-anchor" href="#vanilla-minecraft-conflicts-reminder" aria-label="Permalink to &quot;Vanilla Minecraft Conflicts Reminder&quot;">​</a></h2><p>Here are the normal Minecraft enchants that cannot go together on the same item:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Gear</th><th style="text-align:left;">Conflicting Enchants (Pick Only 1)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pickaxes &amp; Shovels</strong></td><td style="text-align:left;"><strong>Fortune</strong> vs <strong>Silk Touch</strong> (You cannot have both extra diamonds and drop intact blocks).</td></tr><tr><td style="text-align:left;"><strong>Swords</strong></td><td style="text-align:left;"><strong>Sharpness</strong> vs <strong>Smite</strong> vs <strong>Bane of Arthropods</strong>.</td></tr><tr><td style="text-align:left;"><strong>Armor</strong></td><td style="text-align:left;"><strong>Protection</strong> vs <strong>Fire Protection</strong> vs <strong>Blast Protection</strong> vs <strong>Projectile Protection</strong>.</td></tr><tr><td style="text-align:left;"><strong>Bows</strong></td><td style="text-align:left;"><strong>Infinity</strong> (unlimited arrows) vs <strong>Mending</strong> (repairs with XP).</td></tr><tr><td style="text-align:left;"><strong>Crossbows</strong></td><td style="text-align:left;"><strong>Multishot</strong> (3 arrows) vs <strong>Piercing</strong> (arrows shoot through mobs).</td></tr><tr><td style="text-align:left;"><strong>Maces (1.21)</strong></td><td style="text-align:left;"><strong>Density</strong> (more fall damage) vs <strong>Breach</strong> (pierces enemy armor).</td></tr><tr><td style="text-align:left;"><strong>Boots</strong></td><td style="text-align:left;"><strong>Depth Strider</strong> (fast swimming) vs <strong>Frost Walker</strong> (freezes water).</td></tr></tbody></table>',31)])])}const f=e(r,[["render",s]]);export{u as __pageData,f as default};
